const OLD_LINE = 'assert.equal(totalItems, 1870, "Expected 1870 high-yield verified MCQs in maikbook2 (160 OBG + 530 pathology batch 2 + 320 pharmacology batch 2 + 270 ENT + 170 psychiatry + 200 ophthalmology + 220 microbiology)");';
const NEW_LINE = 'assert.equal(totalItems, 1950, "Expected 1950 high-yield verified MCQs in maikbook2 (160 OBG + 530 pathology batch 2 + 320 pharmacology batch 2 + 270 ENT + 170 psychiatry + 200 ophthalmology + 220 microbiology + 80 physiology)");';
